// ── Schedule photo check (AI) ────────────────────────────────────────────────
// Operators upload a photo/screenshot of the cleaning schedule; the server
// (POST /api/ops/schedule-check) asks the Anthropic API to read it and reports
// any of the day's checkouts that are missing from it. Stateless, per-date.
let _opsSched = null; // { date, status: 'running'|'done'|'err', found, missing, extra, note }

function _opsSchedExpected() {
  const { rows } = _opsLoadData(_opsDate);
  return rows
    .filter(r => !r.isCheckinOnly && !r.alreadyCleaned && r.aptName)
    .map(r => ({ name: r.aptName, sameDay: r.checkinSameDay === 'yes' }));
}

function _opsSchedHtml() {
  if (!_opsSched || _opsSched.date !== _opsDate)
    return `<div style="border:1px dashed var(--bdr2);border-radius:var(--r);padding:7px 14px;margin-bottom:12px;font-size:11px;color:var(--tx3)">📸 Κάνε paste (Ctrl+V) ή σύρε εδώ το screenshot του προγράμματος για έλεγχο των checkout — ή πάτα «📸 Check schedule»</div>`;
  const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const wrap = (bdr, inner) => `<div style="background:var(--bg2);border:.5px solid ${bdr};border-radius:var(--r);padding:10px 14px;margin-bottom:12px;font-size:12px;color:var(--tx)">${inner}</div>`;
  if (_opsSched.status === 'running') return wrap('var(--bdr2)', '⏳ Checking the schedule photo against the day&#39;s checkouts…');
  if (_opsSched.status === 'err')     return wrap('#EF4444', '❌ Schedule check failed: ' + esc(_opsSched.note));
  const m  = _opsSched.missing || [];
  const ex = _opsSched.extra   || [];
  let out = '';
  if (!m.length) {
    out += `<div style="font-weight:700;color:#16A34A">✅ Πρόγραμμα ΟΚ — και τα ${(_opsSched.found || []).length} checkout της ημέρας είναι μέσα</div>`;
  } else {
    out += `<div style="font-weight:700;color:#EF4444;margin-bottom:6px">⚠ Λείπουν ${m.length} checkout από το πρόγραμμα:</div>` +
      m.map(x => `<div style="padding:2px 0">• <b>${esc(x.name)}</b>${x.sameDay ? ' <span style="color:#EF4444;font-weight:700">⚡ same-day check-in</span>' : ''}</div>`).join('');
  }
  if (ex.length) out += `<div style="margin-top:8px;color:var(--tx3)">Στο πρόγραμμα χωρίς checkout σήμερα (ΟΚ αν είναι πλυντήρια / μεταφορές / προετοιμασίες): ${ex.map(esc).join(' · ')}</div>`;
  if (_opsSched.note) out += `<div style="margin-top:6px;color:var(--tx3)">${esc(_opsSched.note)}</div>`;
  return wrap(m.length ? '#EF4444' : '#16A34A', out);
}

function _opsSchedRepaint() {
  const box = document.getElementById('ops-schedcheck');
  if (box) box.innerHTML = _opsSchedHtml();
}

function _opsSchedShrink(file) {
  // Downscale phone photos client-side so uploads stay small and cheap
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onerror = () => reject(new Error('Could not read the image'));
    fr.onload = () => {
      const img = new Image();
      img.onload = () => {
        const MAX = 2200;
        let w = img.width, h = img.height;
        if (Math.max(w, h) > MAX) { const k = MAX / Math.max(w, h); w = Math.round(w * k); h = Math.round(h * k); }
        const c = document.createElement('canvas'); c.width = w; c.height = h;
        c.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve({ b64: c.toDataURL('image/jpeg', 0.88).split(',')[1], mime: 'image/jpeg' });
      };
      img.onerror = () => reject(new Error('Unsupported image file'));
      img.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}

async function opsScheduleCheck(file) {
  if (!file) return;
  const expected = _opsSchedExpected();
  if (!expected.length) { toast('No checkouts on this date — nothing to check', 'err'); return; }
  _opsSched = { date: _opsDate, status: 'running' };
  _opsSchedRepaint();
  try {
    const img  = await _opsSchedShrink(file);
    const resp = await fetch('/api/ops/schedule-check', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ dataB64: img.b64, mime: img.mime, date: _opsFmtDate(_opsDate), expected }),
    });
    const d = await resp.json().catch(() => ({}));
    if (!resp.ok || d.error) throw new Error(d.error || ('HTTP ' + resp.status));
    _opsSched = { date: _opsDate, status: 'done', found: d.found || [], missing: d.missing || [], extra: d.extraRows || [], note: d.notes || '' };
    toast(d.missing && d.missing.length ? ('⚠ ' + d.missing.length + ' checkout missing from the schedule') : '✅ Schedule covers every checkout', d.missing && d.missing.length ? 'err' : 'ok');
  } catch (e) {
    _opsSched = { date: _opsDate, status: 'err', note: e.message };
    toast('Schedule check failed: ' + e.message, 'err');
  }
  _opsSchedRepaint();
}

// Paste (Ctrl+V) or drag-and-drop an image anywhere on the Daily Ops tab to
// trigger the schedule check — no button needed.
(function _opsSchedBindOnce() {
  if (window.__opsSchedBound) return;
  window.__opsSchedBound = true;
  const opsActive = () => {
    const el = document.getElementById('tab-ops');
    return !!(el && el.offsetParent !== null);
  };
  document.addEventListener('paste', function (e) {
    if (!opsActive()) return;
    const items = (e.clipboardData && e.clipboardData.items) ? Array.from(e.clipboardData.items) : [];
    let img = null;
    for (const it of items) { if (it.type && it.type.indexOf('image/') === 0) { img = it.getAsFile(); break; } }
    if (!img) return;
    const t = e.target;
    const typing = t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable);
    const hasText = items.some(it => it.kind === 'string');
    if (typing && hasText) return; // pasting Excel cells into a text field — don't hijack
    e.preventDefault();
    opsScheduleCheck(img);
  });
  document.addEventListener('dragover', function (e) {
    if (!opsActive()) return;
    const types = (e.dataTransfer && e.dataTransfer.types) ? Array.from(e.dataTransfer.types) : [];
    if (types.includes('Files')) e.preventDefault();
  });
  document.addEventListener('drop', function (e) {
    if (!opsActive()) return;
    const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
    if (f && f.type && f.type.indexOf('image/') === 0) { e.preventDefault(); opsScheduleCheck(f); }
  });
})();

